WITH enriched AS (SELECT id, device_code, reading_ts, temp_c, humidity, pressure, status_bits, firmware, FIRST_VALUE(humidity) IGNORE NULLS OVER (PARTITION BY device_code ORDER BY status_bits, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) first_known_humidity, AVG(pressure) OVER (PARTITION BY device_code ORDER BY pressure, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) pressure_avg_3, FIRST_VALUE(temp_c, TRUE) OVER (ORDER BY pressure, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) first_known_temp_c, RANK() OVER (ORDER BY pressure DESC) pressure_rank FROM device_readings), filtered AS (SELECT *, CONCAT_WS(',', firmware, device_code) firmware_device_code_key FROM enriched WHERE first_known_temp_c >= 31), enriched_device_readings AS (SELECT id, device_code, reading_ts, temp_c, humidity, pressure, status_bits, firmware, first_known_humidity, pressure_avg_3, first_known_temp_c, pressure_rank, firmware_device_code_key, LEAD(temp_c, 1) OVER (PARTITION BY device_code ORDER BY reading_ts, id) next_temp_c, ROW_NUMBER() OVER w_grp row_seq, LAG(temp_c, 1) OVER w_hist prev_temp_c, MIN(humidity) OVER w_ordered device_code_min_humidity, SUM(first_known_humidity) OVER w_ordered device_code_sum_first_known_humidity FROM filtered WINDOW w_grp AS (ORDER BY pressure_avg_3 DESC, id), w_hist AS (PARTITION BY device_code ORDER BY temp_c, id), w_ordered AS (PARTITION BY device_code)), valid AS (SELECT id, device_code, reading_ts, temp_c, humidity, status_bits, firmware, first_known_humidity, first_known_temp_c, pressure_rank, firmware_device_code_key, next_temp_c, row_seq, prev_temp_c, device_code_sum_first_known_humidity, ROUND(device_code_min_humidity, 0) device_code_min_humidity_rounded, FLOOR(next_temp_c) next_temp_c_whole FROM enriched_device_readings WHERE reading_ts > TO_DATE('2025-09-01') AND first_known_humidity <= 75) SELECT id, reading_ts, temp_c, status_bits, firmware, first_known_humidity, first_known_temp_c, pressure_rank, firmware_device_code_key FROM valid;
